def format_mission(m):
    slug, name, title, cat, desc, deliverables, timeline, roles, faqs = m
    del_str = ", ".join(f'"{d}"' for d in deliverables)
    roles_str = ", ".join(f'"{r}"' for r in roles)
    faq_str = ", ".join(f'{{ question: "{q}", answer: "{a}" }}' for q, a in faqs)
    return (
        f'  {{ slug: "{slug}", name: "{name}", title: "{title}", '
        f'category: "{cat}", description: "{desc}", '
        f'deliverables: [{del_str}], '
        f'timeline: "{timeline}", '
        f'agentRoles: [{roles_str}], '
        f'faq: [{faq_str}] }},'
    )

lines = ['import type { Mission } from "@/types";', '', 'export const missions: Mission[] = [']
for m in MISSIONS:
    lines.append(format_mission(m))
lines.append('];')
lines.append('')

content = '\n'.join(lines)
with open('/Users/adda247/personal/shipsquad/shipsquad-front/src/data/missions.ts', 'w') as f:
    f.write(content)
print(f"Written {len(MISSIONS)} missions to missions.ts ({len(content)} bytes)")
